import{_ as n,o as s,c as e,a8 as l}from"./chunks/framework.DQoZbSQ3.js";const u=JSON.parse('{"title":"Coze 接入熊猫算力教程","description":"","frontmatter":{"title":"Coze 接入熊猫算力教程","date":"2026-05-18T00:00:00.000Z","category":"拓展连接","tags":["Coze","Agent","工作流"]},"headers":[],"relativePath":"connect/coze.md","filePath":"connect/coze.md","lastUpdated":1779095736000}'),o={name:"connect/coze.md"};function t(p,a,i,r,c,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h2 id="什么是-coze" tabindex="-1">什么是 Coze <a class="header-anchor" href="#什么是-coze" aria-label="Permalink to &quot;什么是 Coze&quot;">​</a></h2><p>Coze 是字节跳动推出的 AI Agent 构建平台，支持快速搭建 AI 助手、工作流和插件，无需编程基础，可以发布到飞书、微信、抖音等多个平台。</p><h2 id="在-coze-中使用自定义模型" tabindex="-1">在 Coze 中使用自定义模型 <a class="header-anchor" href="#在-coze-中使用自定义模型" aria-label="Permalink to &quot;在 Coze 中使用自定义模型&quot;">​</a></h2><p>Coze 支持通过 <strong>Model Provider</strong> 功能接入外部模型，步骤如下：</p><ol><li>登录 <a href="https://www.coze.cn" target="_blank" rel="noreferrer">coze.cn</a></li><li>进入 <strong>团队设置 → 模型管理</strong></li><li>点击「添加模型」→ 选择「OpenAI 兼容」</li><li>填写： <ul><li><strong>API Key</strong>：你的熊猫算力 Key</li><li><strong>Base URL</strong>：<code>https://c.pandatoken.com/v1</code></li><li><strong>模型 ID</strong>：<code>claude-sonnet-4-6</code></li></ul></li><li>点击「测试连接」确认成功</li><li>保存后在 Bot 配置中选择该模型</li></ol><h2 id="搭建第一个-ai-bot" tabindex="-1">搭建第一个 AI Bot <a class="header-anchor" href="#搭建第一个-ai-bot" aria-label="Permalink to &quot;搭建第一个 AI Bot&quot;">​</a></h2><ol><li>进入 <strong>Bot → 新建 Bot</strong></li><li>在「模型」下拉框选择你刚添加的 Claude 模型</li><li>在「人设与回复逻辑」填写系统提示词</li><li>点击右上角「测试」验证效果</li><li>满意后点击「发布」选择发布渠道</li></ol><h2 id="实用-bot-配置示例" tabindex="-1">实用 Bot 配置示例 <a class="header-anchor" href="#实用-bot-配置示例" aria-label="Permalink to &quot;实用 Bot 配置示例&quot;">​</a></h2><p><strong>客服 Bot 系统提示词：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是熊猫算力平台的智能客服助手。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>职责：</span></span>
<span class="line"><span>- 解答 API 接入相关问题</span></span>
<span class="line"><span>- 解释计费规则</span></span>
<span class="line"><span>- 处理常见报错</span></span>
<span class="line"><span></span></span>
<span class="line"><span>回复风格：</span></span>
<span class="line"><span>- 简洁直接，先给结论</span></span>
<span class="line"><span>- 提供可复制的代码示例</span></span>
<span class="line"><span>- 无法确定的问题引导用户联系人工客服</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Coze 的工作流功能可以实现多步骤 Agent，比如&quot;收到用户问题 → 搜索知识库 → Claude 生成回答 → 返回用户&quot;，配合熊猫算力的多模型支持，可以在不同步骤用不同模型，降低整体成本。</p></div>`,11)])])}const h=n(o,[["render",t]]);export{u as __pageData,h as default};
